{"contents": "import dpkt
from collections import Counter
from socket import inet_ntoa
f=open('cap.pcap','rb')
r=dpkt.pcap.Reader(f)
c=Counter(); n=0; ports=Counter(); ips=Counter()
pkts=list(r)
for ts,buf in pkts:
    n+=1
    eth=dpkt.ethernet.Ethernet(buf)
    ethtype = eth.type
    c['eth:%d'%ethtype]+=1
    if isinstance(eth.data, dpkt.ip.IP):
        ip=eth.data
        c['ipproto:%d'%ip.p]+=1
        ips[(inet_ntoa(ip.src),inet_ntoa(ip.dst))]+=1
        t=ip.data
        if hasattr(t,'sport'):
            ports[(type(t).__name__, int(t.sport), int(t.dport))]+=1
        else:
            c['ipdata:%s'%type(t).__name__]+=1
    else:
        c['notip:%s'%type(eth.data).__name__]+=1
print("packets",n)
for k,v in c.most_common(30): print(k,v)
print("--- port pairs (proto, sport, dport) counts")
for k,v in ports.most_common(40): print(k,v)
print("--- ip pairs")
for k,v in ips.most_common(20): print(k,v)
